import fs from 'node:fs';
import { test, expect } from './fixtures.js';

// tools.json is generated by the build and lists every page.
const catalog = JSON.parse(fs.readFileSync(new URL('../build/tools.json', import.meta.url), 'utf8'));

test.describe('every page loads without errors', () => {
	const urls = [
		'/tools/',
		'/tools/about/',
		'/tools/contact/',
		...catalog.categories.map((c) => `/tools/${c.id}/`),
		...catalog.pages.map((p) => `/tools/${p.category}/${p.slug}/`)
	];

	for (const url of urls) {
		test(url, async ({ page }) => {
			await page.goto(url);
			await expect(page.locator('h1').first()).toBeVisible();
			// Give lazy code and effects a moment to fail loudly.
			await page.waitForTimeout(150);
		});
	}
});

test('machine readable files are served', async ({ request }) => {
	const llms = await request.get('/tools/llms.txt');
	expect(llms.ok()).toBe(true);
	expect(await llms.text()).toContain('# Mools');
	const sitemap = await request.get('/tools/sitemap.xml');
	expect(await sitemap.text()).toContain('<urlset');
	expect(catalog.tools.length).toBeGreaterThan(70);
});
